                    decisiveCatalyst: `${decisiveCatalyst.ccy} ${decisiveCatalyst.type} (${decisiveCatalyst.period})`,
                    latestConfirmation: `${latestConfirmation.ccy} ${latestConfirmation.type} (${latestConfirmation.period} · ${latestConfirmation.days}d ago)`,
                    scrapedAtDate: '2026-11-05',
                    avgPairDataAgeDays: avgPairAge,
                    baseKeyDates: bDates,
